import React from 'react'

const ChatBlock = (user, typingUsers, messages, messagesEndRef) => {
    function formatTypingMessage(users) {
    const count = users.length;
    console.log(users[0])
    console.log(user.username)
    let exists = users.includes(user.username)
    console.log(exists)
    if (count === 0) return '';
    if (count === 1) return `${users[0] === user.username ? '' : `${users[0]} is typing...`}`;
    // if (count === 2) return `${users[0] === user.username ? `${users[1]} is typing...` : `${users[0]} is typing...`}`;
    if (count >= 2)
      return `${users[0]}, ${users[1]}, and ${count - 1} others are typing...`;
  }

    return (
        <>
            <div style={{
                height: '80vh',
                maxHeight: '80vh',
                border: '1px solid #ccc',
                overflowY: 'auto',
                padding: '10px'
            }}>
                {messages.map((msg, i) => {
                    const isMyMessage = msg.username === user?.username;
                    return (
                        <div
                            key={i}
                            style={{
                                display: 'flex',
                                justifyContent: isMyMessage ? 'flex-end' : 'flex-start',
                                marginBottom: '10px'
                            }}>
                            <div
                                style={{
                                    backgroundColor: isMyMessage ? '#007bff' : '#f1f1f1',
                                    color: isMyMessage ? 'white' : 'black',
                                    padding: '10px 15px',
                                    borderRadius: '10px',
                                    maxWidth: '60%',
                                    wordWrap: 'break-word'
                                }}>
                                <strong >{msg.username}</strong><br />
                                <span><span style={{ paddingRight: '12px' }} >{msg.text}</span><small style={{ fontSize: '9px' }} >{msg.time}</small></span>
                            </div>
                        </div>
                    );
                })}
                <div ref={messagesEndRef} />
                {typingUsers.length > 0 && (
                    <div style={{ fontStyle: 'italic', color: '#666', marginBottom: '5px' }}>
                        {formatTypingMessage(typingUsers)}
                    </div>
                )}
            </div>
        </>
    )
}

export default ChatBlock
